using System;using UnityEngine;using EchoSphere.Core;
namespace EchoSphere.Presentation {
 internal sealed partial class NativeWorldCreatures {
  private void RegionalSignalLine(double ax,double ay,double bx,double by,Color color,double width){double dx=bx-ax,dy=by-ay,d=Math.Sqrt(dx*dx+dy*dy);if(d<.001)return;var line=Get(27800,0,0,1,()=>Straight(Vector2.zero,P(1,0)),false);Paint(line,T(ax,ay,Math.Atan2(dy,dx),d,width),null,color,forceOver:true,shadow:Color.clear);}
  private void DrawRegionalMechanicSignals(EnemyView e,Matrix4x4 root){
   if(e.CrystalShield||e.CrystalOpen>0){double open=e.CrystalShield?0:1,r=e.Radius;var facet=Get(27801,r,0,1.2,()=>Poly(P(-r*.35,-r*.12),P(r*.35,-r*.12),P(r*.48,r*.12),P(0,r*.28),P(-r*.48,r*.12)));for(int side=-1;side<=1;side+=2)Paint(facet,root*T(0,side*r*(.55+open*.35),side*open*.35,sy:side),A(C(100,225,250),e.CrystalShield?.22:.04),A(C(185,250,255),e.CrystalShield?.9:.45),forceOver:true,shadow:Color.clear);}
   if(e.EnergyLink){var color=e.EnergyFlash>0?C(255,255,235):C(255,201,80,.72);double dx=e.EnergyX-e.X,dy=e.EnergyY-e.Y;for(int i=0;i<5;i++){double a=i/5d,b=(i+1)/5d,za=i==0?0:(i%2==0?4:-4),zb=i==4?0:((i+1)%2==0?4:-4),len=Math.Max(1,Math.Sqrt(dx*dx+dy*dy));RegionalSignalLine(e.X+dx*a-dy/len*za,e.Y+dy*a+dx/len*za,e.X+dx*b-dy/len*zb,e.Y+dy*b+dx/len*zb,color,e.EnergyFlash>0?3:1.3);}}
   if(e.GroundMark){double radius=RegionalCombatTuning.ShadowRadius;var area=Get(27802,radius,0,1.6,()=>Oval(radius,radius));Paint(area,T(e.GroundX,e.GroundY),C(126,51,191,.16),C(207,126,255,.85),forceOver:true,shadow:Color.clear);var cross=Get(27803,radius,0,1.2,()=>Straight(P(-radius*.65,0),P(radius*.65,0)),false);Paint(cross,T(e.GroundX,e.GroundY),null,C(238,193,255,.65),forceOver:true,shadow:Color.clear);Paint(cross,T(e.GroundX,e.GroundY,Math.PI*.5),null,C(238,193,255,.65),forceOver:true,shadow:Color.clear);}
   if(!e.Boss&&e.Role=="sniper"&&e.AttackWindup>0){double range=RegionalEnemyRules.Get(e.RegionStyle,e.Role).Range;RegionalSignalLine(e.X,e.Y,e.X+Math.Cos(e.AimAngle)*range,e.Y+Math.Sin(e.AimAngle)*range,C(255,162,105,.65),1.2);}
   if(e.RegionStyle==0&&(e.Role=="healer"||e.Role=="disruptor")&&e.AttackPose>0){var ring=Get(27804,e.Radius,0,1.2,()=>Oval(e.Radius*1.5,e.Radius*1.5));Paint(ring,T(e.X,e.Y),null,A(e.Role=="healer"?C(120,255,163):C(210,145,255),Clamp(e.AttackPose)),forceOver:true,shadow:Color.clear);}
  }
  private void DrawSummonerHatches(EnemyView e,Matrix4x4 root){if(e.Variant!="brood_queen"&&e.Variant!="fleet_carrier"&&!(e.RegionStyle==2&&e.Role=="anchor"))return;double r=e.Radius,p=Clamp(e.HatchPose);bool queen=e.RegionStyle==2;var plate=Get(27810+(queen?1:0),r,0,1.2,()=>queen?Poly(P(-r*.65,-r*.20),P(-r*.1,-r*.35),P(r*.50,-r*.12),P(r*.60,r*.18),P(0,r*.33),P(-r*.60,r*.12)):Poly(P(-r*.70,-r*.15),P(r*.60,-r*.15),P(r*.78,r*.14),P(-r*.60,r*.23)));for(int side=-1;side<=1;side+=2){var joint=root*T(-r*.12,side*r*(.40+p*.27),side*p*.28,sy:side);Paint(plate,joint,C(6,15,22,.98),e.Color,forceOver:true,shadow:Color.clear);for(int i=0;i<3;i++){var slot=Get(27812,r,0,1,()=>Straight(P(0,-r*.08),P(0,r*.08)),false);Paint(slot,joint*T((- .35+i*.30)*r),null,A(e.Color,.6+p*.4),forceOver:true,shadow:Color.clear);}}if(p>0)RegionalEllipse(root,r*.25,r*.45,A(e.Color,p*.35),A(Color.white,p*.70));}
 }
}
